import{_ as t,a,o as i,a6 as n}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"Email Templates","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/marketing/communications/templates/index.md","filePath":"api/graphql-api/admin/marketing/communications/templates/index.md","lastUpdated":1787725411000}'),o={name:"api/graphql-api/admin/marketing/communications/templates/index.md"};function r(s,e,m,d,l,p){return i(),a("div",null,e[0]||(e[0]=[n('<h1 id="email-templates" tabindex="-1">Email Templates <a class="header-anchor" href="#email-templates" aria-label="Permalink to &quot;Email Templates&quot;">​</a></h1><p>An <strong>email template</strong> is a reusable HTML email body that a campaign sends to a customer group. It mirrors the admin <strong>Marketing → Communications → Email Templates</strong> screen.</p><h2 id="how-an-email-template-works" tabindex="-1">How an email template works <a class="header-anchor" href="#how-an-email-template-works" aria-label="Permalink to &quot;How an email template works&quot;">​</a></h2><p>A template has three parts: a <strong>name</strong> to identify it, a <strong>status</strong> that controls whether it can be used, and the <strong>content</strong> — the raw HTML of the email.</p><ul><li><strong><code>name</code></strong> — a human-readable label for the template in the admin list.</li><li><strong><code>status</code></strong> — one of <code>active</code>, <code>inactive</code>, or <code>draft</code>. Only active templates are intended for live sends; <code>draft</code> and <code>inactive</code> let you stage a template before it goes out.</li><li><strong><code>content</code></strong> — the raw HTML body of the email. Whatever markup you save here is the message recipients receive.</li></ul><p><strong>How it&#39;s used.</strong> A template is referenced by a <strong>Campaign</strong>, which pairs the template with a customer group (and optionally an event) and sends it. Editing a template changes what every campaign that references it will send next.</p><p><strong>No mass delete.</strong> The admin screen exposes single-row delete only — there is no bulk delete for email templates.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/marketing/communications/templates-list.html">List</a></td><td><code>adminMarketingTemplates</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/templates-detail.html">Detail</a></td><td><code>adminMarketingTemplate</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/templates-create.html">Create</a></td><td><code>createAdminMarketingTemplate</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/templates-update.html">Update</a></td><td><code>updateAdminMarketingTemplate</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/communications/templates-delete.html">Delete</a></td><td><code>deleteAdminMarketingTemplate</code> mutation</td></tr></tbody></table>',9)]))}const g=t(o,[["render",r]]);export{h as __pageData,g as default};
